<template><div class="page-container fsr-page"><div class="page-head"><div><h2>现场核查整改库</h2><p>区分核查责任与整改责任，沉淀现场证据和整改闭环。</p></div><el-button type="primary" @click="load">刷新整改记录</el-button></div><div class="panel"><div class="panel-title">现场核查整改列表</div><el-tabs v-model="tab"><el-tab-pane v-for="i in tabs" :key="i.value" :label="`${i.label}（${groups[i.value].length}）`" :name="i.value"><el-table :data="groups[i.value]" stripe border><el-table-column prop="code" label="图斑编号" width="150"/><el-table-column prop="regionName" label="所在位置" min-width="140"/><el-table-column label="现场照片" width="90"><template #default="{row}">{{ row.checkReport?.photos||0 }}张</template></el-table-column><el-table-column label="现场视频" width="90"><template #default="{row}">{{ row.checkReport?.videos||0 }}个</template></el-table-column><el-table-column label="文字描述" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.checkReport?.desc||'待录入' }}</template></el-table-column><el-table-column label="GPS定位" width="150"><template #default="{row}">{{ row.checkReport?.gps||'待采集' }}</template></el-table-column><el-table-column label="核查结论" width="100"><template #default="{row}">{{ row.checkReport?.conclusion||'待核查' }}</template></el-table-column><el-table-column label="整改责任人" min-width="140"><template #default="{row}">{{ row.rectificationResponsiblePerson||'待明确' }}</template></el-table-column><el-table-column label="措施时限" width="120"><template #default="{row}">{{ row.rectifyDeadline||'待制定' }}</template></el-table-column><el-table-column label="整改完成情况" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.completionDescription||row.rectifyNote?.desc||'待提交' }}</template></el-table-column><el-table-column label="操作" width="230" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看</el-button><el-button v-if="i.value==='checking'||i.value==='recheck'" link type="success" @click="openCheck(row)">录入核查</el-button><el-button v-if="i.value==='rectifying'" link type="warning" @click="openRectify(row)">提交整改</el-button><el-button v-if="i.value==='reviewing'" link type="primary" @click="operate(row,'pass')">审核通过</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></div><el-dialog v-model="visible" title="现场核查整改详情" width="820px"><template v-if="current"><el-descriptions :column="3" border><el-descriptions-item label="图斑编号">{{ current.code }}</el-descriptions-item><el-descriptions-item label="状态">{{ statusName(current.status) }}</el-descriptions-item><el-descriptions-item label="核查责任人">{{ current.checkResponsiblePerson||current.assignee||'待明确' }}</el-descriptions-item><el-descriptions-item label="核查时间">{{ current.checkedAt||'待核查' }}</el-descriptions-item><el-descriptions-item label="核查结论">{{ current.checkReport?.conclusion||'待核查' }}</el-descriptions-item><el-descriptions-item label="现场照片/视频">{{ current.checkReport?.photos||0 }}张 / {{ current.checkReport?.videos||0 }}个</el-descriptions-item><el-descriptions-item label="GPS定位">{{ current.checkReport?.gps||'待采集' }}</el-descriptions-item><el-descriptions-item label="文字描述" :span="3">{{ current.checkReport?.desc||'待录入' }}</el-descriptions-item><el-descriptions-item label="整改责任人">{{ current.rectificationResponsiblePerson||'待明确' }}</el-descriptions-item><el-descriptions-item label="整改时限">{{ current.rectifyDeadline||'待制定' }}</el-descriptions-item><el-descriptions-item label="整改完成情况" :span="3">{{ current.completionDescription||current.rectifyNote?.desc||'待提交' }}</el-descriptions-item><el-descriptions-item label="整改后现场情况" :span="3">{{ current.rectifyNote?.afterSituation||'待复核采集' }}</el-descriptions-item></el-descriptions></template></el-dialog><el-dialog v-model="formVisible" :title="formAction==='check'?'现场核查录入':'整改提交'" width="560px"><el-form label-width="105px"><template v-if="formAction==='check'"><el-form-item label="核查结论"><el-input v-model="checkForm.conclusion"/></el-form-item><el-form-item label="文字描述"><el-input v-model="checkForm.desc" type="textarea"/></el-form-item><el-form-item label="经纬度"><el-input v-model="checkForm.gps" placeholder="经度,纬度"/></el-form-item><el-form-item label="照片数量"><el-input-number v-model="checkForm.photos" :min="0"/></el-form-item><el-form-item label="视频数量"><el-input-number v-model="checkForm.videos" :min="0"/></el-form-item><el-form-item label="核查责任人"><el-input v-model="checkForm.checker"/></el-form-item></template><template v-else><el-form-item label="整改责任人"><el-input v-model="rectifyForm.rectificationResponsiblePerson"/></el-form-item><el-form-item label="整改措施"><el-input v-model="rectifyForm.measure" type="textarea"/></el-form-item><el-form-item label="整改时限"><el-date-picker v-model="rectifyForm.rectifyDeadline" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="完成情况"><el-input v-model="rectifyForm.completionDescription" type="textarea"/></el-form-item><el-form-item label="整改后照片/视频"><el-input-number v-model="rectifyForm.photos" :min="0"/><el-input-number v-model="rectifyForm.videos" :min="0"/></el-form-item></template></el-form><template #footer><el-button @click="formVisible=false">取消</el-button><el-button type="primary" @click="submitForm">提交</el-button></template></el-dialog></div></template>
<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { fetchEvents,submitCheckReport,submitRectify,auditEvent } from '@/api/fsr';import { useUserStore } from '@/stores/user';const userStore=useUserStore();const rows=ref([]);const tab=ref('checking');const visible=ref(false);const formVisible=ref(false);const current=ref(null);const formAction=ref('check');const checkForm=reactive({conclusion:'',desc:'',gps:'',photos:0,videos:0,checker:''});const rectifyForm=reactive({rectificationResponsiblePerson:'',measure:'',rectifyDeadline:'',completionDescription:'',photos:0,videos:0});const tabs=[{label:'待核查',value:'checking'},{label:'待审核',value:'reviewing'},{label:'已审核',value:'rectifying'},{label:'需复查',value:'recheck'}];const groups=reactive({checking:[],reviewing:[],rectifying:[],recheck:[]});const maps={checking:'待核查',reviewing:'待审核',rectifying:'已审核',recheck:'需复查',closed:'已结案',pending:'已下发'};const statusName=x=>maps[x]||'未知状态';const load=async()=>{rows.value=await fetchEvents(userStore.role,{});tabs.forEach(i=>groups[i.value]=rows.value.filter(e=>e.status===i.value))};const open=r=>{current.value=r;visible.value=true};const openCheck=r=>{current.value=r;formAction.value='check';Object.assign(checkForm,{conclusion:r.checkReport?.conclusion||'',desc:r.checkReport?.desc||'',gps:r.checkReport?.gps||'',photos:r.checkReport?.photos||0,videos:r.checkReport?.videos||0,checker:r.checkResponsiblePerson||''});formVisible.value=true};const openRectify=r=>{current.value=r;formAction.value='rectify';Object.assign(rectifyForm,{rectificationResponsiblePerson:r.rectificationResponsiblePerson||'',measure:'',rectifyDeadline:r.rectifyDeadline||'',completionDescription:'',photos:0,videos:0});formVisible.value=true};const submitForm=async()=>{let result;if(formAction.value==='check'){if(!checkForm.conclusion.trim())return ElMessage.warning('请填写核查结论');result=await submitCheckReport(current.value.id,checkForm)}else{if(!rectifyForm.rectificationResponsiblePerson.trim())return ElMessage.warning('请填写整改责任人');result=await submitRectify(current.value.id,{...rectifyForm,desc:rectifyForm.completionDescription,afterSituation:`整改后现场照片${rectifyForm.photos}张、视频${rectifyForm.videos}个`})}if(!result?.success)return ElMessage.error(result?.message||'提交失败');ElMessage.success('提交成功');formVisible.value=false;load()};const operate=async(r,a)=>{const result=await auditEvent(r.id,'pass','核查材料完整，进入整改',userStore.role?.name||'审核人');if(!result?.success)return ElMessage.error(result.message||'审核失败');load()};onMounted(load)
</script><style scoped lang="scss">.fsr-page{overflow:auto}.page-head{display:flex;justify-content:space-between;margin-bottom:14px}.page-head h2{margin:4px 0;font-size:22px}.page-head p{margin:0;color:var(--ah-text-secondary);font-size:13px}.panel-title{margin-bottom:12px;font-weight:700}</style>